def prov(status, refs):
    return {"status": status, "source_refs": list(dict.fromkeys(refs))}


def not_applicable(reason, refs, status="validated"):
    return {"status": "not_applicable", "reason": reason, "provenance": prov(status, refs)}


def located(device_id, records, refs):
    if not records:
        return None
    placements = []
    statuses = []
    for index, record in enumerate(records, start=1):
        status = record["status"]
        statuses.append(status)
        placements.append({
            "id": f"{device_id}.placement-{index}",
            "role": record["role"],
            "space": "playfield",
            "x": record["x"],
            "y": record["y"],
            "provenance": prov(status, refs),
        })
    overall = "candidate" if "candidate" in statuses else "observed"
    return {"status": overall, "placements": placements}


def switch_spatial(address, device_id):
    records = RESOLUTION["switches"].get(str(address))
    return located(device_id, records, [TABLE, SCRIPT_REF, PRODUCTION]) if records else None


def output_spatial(address, device_id):
    records = RESOLUTION["outputs"].get(str(address))
    return located(device_id, records, [TABLE, SCRIPT_REF, PRODUCTION]) if records else None


def lamp_spatial(address, device_id):
    records = RESOLUTION["lamps"].get(str(address))
    return located(device_id, records, [TABLE, SCRIPT_REF, PRODUCTION]) if records else None


def matrix_wiring(address, drives, returns):
    column = (address - 1) // 8
    row = (address - 1) % 8
    return {
        "board": "CPU Board",
        "drive_wire": drives[column],
        "return_wire": returns[row],
    }


