def mechanism(identifier, label, kind, actuators, sensors, behavior, status="validated", refs=(SCRIPT_REF, PRODUCTION), **extra):
    result = {
        "id": identifier, "label": label, "kind": kind,
        "actuators": actuators, "sensors": sensors, "behavior": behavior,
        "provenance": prov(status, refs),
    }
    result.update(extra)
    return result


